import{_ as o,o as a,c as i,ak as t}from"./chunks/framework.CYL5YPWS.js";const g=JSON.parse('{"title":"Facebook","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/third-party-integrations/facebook.md","filePath":"generated/grindr-api/third-party-integrations/facebook.md"}'),c={name:"grindr-api/third-party-integrations/facebook.md"};function d(n,e,s,r,h,l){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="facebook" tabindex="-1">Facebook <a class="header-anchor" href="#facebook" aria-label="Permalink to “Facebook”">​</a></h1><p>Facebook endpoints reached while signing in. Served by Meta, not Grindr — documented because the resulting access token is what <a href="/grindr-api/authentication#login-via-third-party-wip">Login via third party</a> consumes as <code>thirdPartyToken</code>.</p><h2 id="facebook-login-dialog" tabindex="-1">Facebook login dialog <a class="header-anchor" href="#facebook-login-dialog" aria-label="Permalink to “Facebook login dialog”">​</a></h2><p>Facebook&#39;s OAuth authorization dialog — the only step of <a href="/grindr-api/authentication#login-via-third-party-wip">Sign in with Facebook</a> served by Meta over HTTP, and the source of the <code>thirdPartyToken</code> that Grindr&#39;s backend consumes.</p><p><code>{graphApiVersion}</code> tracks the Graph API version of the bundled Facebook SDK: <code>v16.0</code> with SDK 18.1.3 (app v26.9.2), <code>v14.0</code> with 14.1.1 (v25.20.0).</p><p>Two variants reach this URL and their parameter sets differ; parameters specific to one say so below, everything else is sent by both. The <strong>Custom Tab</strong> variant redirects to <code>fb1273378622718674://authorize/</code> and uses PKCE. The <strong>WebView</strong> variant redirects to the app-independent constant <code>fbconnect://success</code> (<code>fbconnect://chrome_os_success</code> on Chrome OS) and uses no PKCE.</p><p>On completion the browser is redirected to <code>redirect_uri</code> with the result in the fragment (or query): <code>access_token</code>, <code>expires_in</code>, <code>data_access_expiration_time</code>, <code>granted_scopes</code>, <code>denied_scopes</code>, <code>expired_scopes</code>, <code>graph_domain</code> and <code>signed_request</code> on success, or <code>error</code>/<code>error_type</code>, <code>error_msg</code>/<code>error_message</code>/<code>error_description</code> and <code>error_code</code> on failure. A redirect carrying a <code>code</code> and no <code>access_token</code> is exchanged at <a href="/grindr-api/third-party-integrations/facebook#exchange-facebook-auth-code-wip">Exchange Facebook auth code</a>. Only the access-token string is needed for the Grindr sign-in that follows.</p><p>Two further Graph calls precede any login and are not documented as operations here, because neither is on the path of obtaining a token: <code>GET /{graphApiVersion}/app?fields=…</code> (app settings, which supply the <code>cct_prefetching</code> value and the dialog configs) and <code>GET /{graphApiVersion}/app/mobile_sdk_gk?platform=android&amp;sdk_version=…&amp;fields=gatekeepers</code>. Both carry the app access token and are cached on the device.</p><p>No key hash, package name or app signature is computed or transmitted anywhere in this flow.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET https://m.facebook.com/{graphApiVersion}/dialog/oauth</span></span></code></pre></div><p>Query:</p><ul><li><code>client_id</code> — string with the Facebook app id. Grindr&#39;s is <code>1273378622718674</code>, unchanged from v25.20.0 to v26.15.1</li><li><code>redirect_uri</code> — string with the custom-scheme URI the dialog redirects to when it finishes. <code>fb1273378622718674://authorize/</code> on the Custom Tab path; <code>fbconnect://success</code> on the WebView path, or <code>fbconnect://chrome_os_success</code> on Chrome OS. <code>fbconnect://cct.com.grindrapp.android</code> replaces the first when the <code>fb&lt;app id&gt;</code> scheme resolves to no local activity</li><li><code>response_type</code> — string, comma-separated. <code>id_token,token,signed_request,graph_domain</code> on the Custom Tab path; <code>token,signed_request,graph_domain</code> on the WebView path, which requests no OIDC token</li><li><code>scope</code> — string, comma-separated permissions. Grindr requests <code>public_profile</code> and <code>email</code>, and <code>openid</code> is added unconditionally, so all three go out on every path, optional</li><li><code>state</code> — string with a JSON object round-tripped for CSRF and logging: <code>0_auth_logger_id</code> (a UUID), <code>3_method</code> (<code>custom_tab</code> or <code>web_view</code>) and, on the Custom Tab path, <code>7_challenge</code> (20 random characters, checked on the way back), optional</li><li><code>auth_type</code> — string, always <code>rerequest</code>, optional</li><li><code>default_audience</code> — string, always <code>friends</code>. Only meaningful for publish permissions, which Grindr does not request, optional</li><li><code>login_behavior</code> — string, always <code>NATIVE_WITH_FALLBACK</code>, optional</li><li><code>sdk</code> — string identifying the caller, e.g. <code>android-18.1.3</code>, optional</li><li><code>e2e</code> — string with a JSON object holding end-to-end timing marks, e.g. <code>{&quot;init&quot;:&lt;unix ms&gt;}</code>, optional</li><li><code>cbt</code> — string with the client&#39;s millisecond timestamp as the dialog is built, optional</li><li><code>ies</code> — string flag, <code>0</code> for Grindr, which ships with auto app-event logging disabled, optional</li><li><code>return_scopes</code> — string, always <code>true</code>; asks the redirect to carry <code>granted_scopes</code> and <code>denied_scopes</code>, optional</li><li><code>nonce</code> — string with a UUID, echoed inside the returned <code>id_token</code>. Custom Tab path only, optional</li><li><code>code_challenge</code> — string, the S256 PKCE challenge derived from a 43-128 character verifier. Custom Tab path only; the WebView path sends no PKCE at all, optional</li><li><code>code_challenge_method</code> — string, always <code>S256</code>. Custom Tab path only, optional</li><li><code>display</code> — string, always <code>touch</code>. WebView path only, optional</li><li><code>sso</code> — string, always <code>chrome_custom_tab</code>. Custom Tab path only, optional</li><li><code>cct_prefetching</code> — string flag, <code>1</code> when Custom Tabs prefetching is enabled, <code>0</code> otherwise, optional</li><li><code>cct_over_app_switch</code> — string, always <code>1</code> when present. Custom Tab path only, and only after a native app-switch handler bailed out with <code>error=logged_out</code>; otherwise the key is absent, optional</li><li><code>access_token</code> — string with a cached Facebook access token, sent to let Facebook skip re-authentication when it is still valid, optional</li></ul><p>Response:</p><p>Facebook&#39;s login and consent page. The result is read from the <code>redirect_uri</code> navigation, not from this body.</p><h2 id="exchange-facebook-auth-code-wip" tabindex="-1">Exchange Facebook auth code, WIP <a class="header-anchor" href="#exchange-facebook-auth-code-wip" aria-label="Permalink to “Exchange Facebook auth code, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><p>PKCE authorization-code exchange, reached whenever a redirect comes back with a <code>code</code> and no <code>access_token</code> — from <a href="/grindr-api/third-party-integrations/facebook#facebook-login-dialog">Facebook login dialog</a> on the Custom Tab path, or from a native app-switch handler, which forwards a code challenge of its own without ever loading that URL. The WebView path carries no PKCE and so never reaches here.</p><p>Being a Graph call it also carries <code>sdk=android</code>, <code>format=json</code> and an app access token <code>access_token=&lt;app id&gt;|&lt;client token&gt;</code> — for Grindr <code>1273378622718674|5524d0b5439620826256ca48978b95a3</code>, both halves shipped in the APK&#39;s string resources and unchanged from v25.20.0 to v26.15.1.</p><p>The <code>access_token</code> from the response is what ends up in <code>thirdPartyToken</code> on <a href="/grindr-api/authentication#login-via-third-party-wip">Login via third party</a>.</p><p>Response type: <code>FacebookAccessTokenResponse</code> (undocumented).</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET https://graph.facebook.com/{graphApiVersion}/oauth/access_token</span></span></code></pre></div><p>Query:</p><ul><li><code>code</code> — string with the authorization code from the dialog redirect</li><li><code>client_id</code> — string with the Facebook app id, <code>1273378622718674</code> for Grindr</li><li><code>redirect_uri</code> — string, the same redirect URI the dialog was opened with</li><li><code>code_verifier</code> — string, the 43-128 character PKCE verifier whose S256 hash was sent as <code>code_challenge</code></li></ul><p>Response:</p><p>Standard Facebook OAuth token payload carrying <code>access_token</code> and its lifetime.</p><h2 id="fetch-facebook-profile-wip" tabindex="-1">Fetch Facebook profile, WIP <a class="header-anchor" href="#fetch-facebook-profile-wip" aria-label="Permalink to “Fetch Facebook profile, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><p>Fetched after every successful login: the freshly minted user access token is sent here and the profile cached.</p><p>Nothing in the Grindr sign-in path reads the result — the identity Grindr uses is the <code>thirdPartyUserInfo</code> its own backend returns from <a href="/grindr-api/authentication#login-via-third-party-wip">Login via third party</a> — so a re-implementation that only needs the access token can skip this call.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET https://graph.facebook.com/{graphApiVersion}/me</span></span></code></pre></div><p>Query:</p><ul><li><code>fields</code> — string, comma-separated. <code>id,name,first_name,middle_name,last_name</code> for a Facebook-domain token; <code>id,name,profile_picture</code> for an Instagram-domain one, which Grindr never requests, optional</li><li><code>access_token</code> — string, the user access token just obtained</li></ul><p>Response:</p><p>Facebook profile JSON for the fields requested.</p><h2 id="facebook-oidc-keys-wip" tabindex="-1">Facebook OIDC keys, WIP <a class="header-anchor" href="#facebook-oidc-keys-wip" aria-label="Permalink to “Facebook OIDC keys, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><p>OIDC JSON Web Key Set, fetched to verify the <code>id_token</code> that <a href="/grindr-api/third-party-integrations/facebook#facebook-login-dialog">Facebook login dialog</a> returns on the Custom Tab and native app-switch paths: the signature is checked against the key matching the JWT header&#39;s <code>kid</code>.</p><p>Unversioned and unauthenticated — no app id, client token or user token is sent. The WebView path asks for no <code>id_token</code> and never reaches it, and Grindr never reads the <code>id_token</code>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET https://www.facebook.com/.well-known/oauth/openid/keys/</span></span></code></pre></div><p>Response:</p><p>JWKS document.</p>',41)])])}const k=o(c,[["render",d]]);export{g as __pageData,k as default};
